CREATE OR REPLACE FUNCTION public.canonical_asset_registry_jsonb(input_value jsonb)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE PARALLEL SAFE STRICT
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
        DECLARE
          value_type TEXT;
          rendered TEXT;
        BEGIN
          value_type := jsonb_typeof(input_value);
          CASE value_type
            WHEN 'object' THEN
              SELECT '{' || COALESCE(
                       string_agg(
                         to_jsonb(item.key)::TEXT || ':' ||
                           canonical_asset_registry_jsonb(item.value),
                         ',' ORDER BY item.key COLLATE "C"
                       ),
                       ''
                     ) || '}'
                INTO rendered
                FROM jsonb_each(input_value) AS item;
              RETURN rendered;
            WHEN 'array' THEN
              SELECT '[' || COALESCE(
                       string_agg(
                         canonical_asset_registry_jsonb(item.value),
                         ',' ORDER BY item.ordinality
                       ),
                       ''
                     ) || ']'
                INTO rendered
                FROM jsonb_array_elements(input_value)
                     WITH ORDINALITY AS item(value, ordinality);
              RETURN rendered;
            WHEN 'number' THEN
              rendered := input_value::TEXT;
              IF POSITION('.' IN rendered) > 0 THEN
                rendered := (rendered::DOUBLE PRECISION)::TEXT;
                IF POSITION('.' IN rendered) = 0
                   AND POSITION('e' IN rendered) = 0 THEN
                  rendered := rendered || '.0';
                END IF;
              END IF;
              RETURN rendered;
            ELSE
              RETURN input_value::TEXT;
          END CASE;
        END;
        $function$
